// Quick-reply chips. Every suggestion is derived from the site's own pages
// or from the passages just retrieved, never generated by the model, so a
// chip can only ever ask about something the index can answer.

const MAX_LABEL = 44;

function short(text, limit = MAX_LABEL) {
  const value = String(text ?? '').replace(/\s+/g, ' ').trim();
  return value.length > limit ? `${value.slice(0, limit - 1).trimEnd()}…` : value;
}

/** Chips shown before the first question: the site's biggest pages. */
export function pageChips(pages, limit = 3) {
  const out = [];
  const seen = new Set();
  for (const page of pages || []) {
    const title = String(page?.title ?? '').replace(/\s+/g, ' ').trim();
    if (!title) continue;
    const key = title.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      label: short(title),
      question: /\?$/.test(title) ? title : `Tell me about ${title}`
    });
    if (out.length >= limit) break;
  }
  return out;
}

// A citation chip has room for a page name, not a breadcrumb. Ingested titles
// read "Section > Section > Page, Site", so keep the last crumb and drop the
// trailing site name.
const TITLE_SEPARATORS = [`${String.fromCharCode(0x2014)} `, ' – ', ' - ', ', '];

export function sourceLabel(title, limit = 34) {
  let value = String(title ?? '').replace(/\s+/g, ' ').trim();
  const crumb = value.split('>').pop().trim();
  if (crumb) value = crumb;
  for (const separator of TITLE_SEPARATORS) {
    const at = value.lastIndexOf(separator);
    if (at > 0) {
      value = value.slice(0, at).trim();
      break;
    }
  }
  return short(value, limit);
}

/** One citation per page: retrieval often returns four chunks of one page. */
export function groupSources(passages) {
  const out = [];
  const byKey = new Map();
  for (const [index, passage] of (passages || []).entries()) {
    const key = passage?.url || passage?.title || `#${index}`;
    const seen = byKey.get(key);
    if (seen) {
      seen.count += 1;
    } else {
      const entry = {
        index: index + 1,
        title: passage?.title || '',
        url: passage?.url || '',
        count: 1
      };
      byKey.set(key, entry);
      out.push(entry);
    }
  }
  return out;
}

/** Chips after an answer: the sections it actually used. */
export function followUpChips(passages, limit = 3) {
  const out = [];
  const seen = new Set();
  for (const passage of passages || []) {
    const heading = String(passage?.heading || passage?.title || '').replace(/\s+/g, ' ').trim();
    if (!heading) continue;
    const key = heading.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ label: short(heading), question: `More about ${heading}` });
    if (out.length >= limit) break;
  }
  return out;
}
